import{_ as o,C as i,c as r,o as n,j as a,G as s,ag as l,a as d}from"./chunks/framework.DZ_cNctr.js";const h="/docs/screenshots/scn-slide.webp",S=JSON.parse('{"title":"Leica SCN Slides in the Browser","titleTemplate":"Find Nuclei: :title","description":"Find Nuclei opens Leica SCN slides in your browser: every scanned region, brightfield and fluorescence. Free, nothing to install or convert.","frontmatter":{"title":"Leica SCN Slides in the Browser","titleTemplate":"Find Nuclei: :title","description":"Find Nuclei opens Leica SCN slides in your browser: every scanned region, brightfield and fluorescence. Free, nothing to install or convert."},"headers":[],"relativePath":"guides/leica-scn.md","filePath":"guides/leica-scn.md"}'),c={name:"guides/leica-scn.md"};function p(u,e,f,m,g,w){const t=i("OpenViewer");return n(),r("div",null,[e[0]||(e[0]=a("h1",{id:"leica-scn-slides-in-the-browser",tabindex:"-1"},[d("Leica SCN Slides in the Browser "),a("a",{class:"header-anchor",href:"#leica-scn-slides-in-the-browser","aria-label":'Permalink to "Leica SCN Slides in the Browser"'},"​")],-1)),e[1]||(e[1]=a("p",null,"Open the slides your Leica SCN400 saves, with every scanned region, brightfield and fluorescence. The viewer reads only the part you look at, so a large slide opens without reading all of it first.",-1)),s(t,{format:"SCN",example:"https://find-nuclei.github.io/examples/formats/Leica-Fluorescence-1.scn",label:"a fluorescence slide in SCN"}),e[2]||(e[2]=l('<p><img src="'+h+'" alt="Leica-2.scn open in the viewer: a kidney section, the Macro picture in the side panel, and the Series gallery under the slide with its four regions as pictures"></p><h2 id="how-to-open-an-scn-file" tabindex="-1">How to Open an SCN File <a class="header-anchor" href="#how-to-open-an-scn-file" aria-label="Permalink to &quot;How to Open an SCN File&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Working with many files?</p><p>Chrome and Edge on a computer open a whole folder as a <a href="./many-images.html">gallery</a>. Firefox and Safari open one file at a time.</p></div><ul><li><strong>One file on your disk</strong>, in any browser. Drop it on <a href="https://find-nuclei.github.io/" target="_blank" rel="noreferrer">the viewer</a>, or click <strong>Open Image</strong> and <strong>Choose File</strong>. See <a href="./local-files.html#open-a-file">Local Files</a>.</li><li><strong>A folder of slides</strong>, in Chrome and Edge. One slide opens. Several show a list with a picture of each. After you pick one, a gallery of pictures under the image takes you to the next. See <a href="./many-images.html">Folders, Zips and Series</a>.</li><li><strong>An address</strong>: <code>https://</code>, <code>s3://</code> or <code>gs://</code>. Paste it under <strong>Open Image</strong>. See <a href="./remote-urls.html">Remote URLs</a>.</li><li><strong>Private data</strong>, with a private link or a token. See <a href="./authenticated-sources.html">Private Images and Slides</a>.</li></ul><h2 id="what-you-will-see" tabindex="-1">What You Will See <a class="header-anchor" href="#what-you-will-see" aria-label="Permalink to &quot;What You Will See&quot;">​</a></h2><ul><li><strong>Regions.</strong> A slide can hold several scanned regions. Click <strong>Series</strong> on the status bar for a gallery of pictures under the slide, one per region, such as <strong>Region 1 (40x)</strong>, and click one to open it. On a phone, pick from the <strong>Region</strong> list in the side panel. See <a href="./many-images.html#series-inside-one-file">Series Inside One File</a>.</li><li><strong>Macro.</strong> It appears under the title. Click it to enlarge it, and turn it if needed. A label may show patient details. The viewer shows it and never saves or sends it.</li><li><strong>Fluorescence.</strong> Each channel opens with its own colour and contrast.</li><li><strong>Colour profile.</strong> A slide that carries its scanner&#39;s colour profile is drawn with it. ICC in the RGB settings turns it off. See <a href="./channels.html#icc-colour-profile">Channels</a>.</li><li><strong>Z-stacks.</strong> The first plane opens, with a note.</li><li><strong>Pixel size and magnification.</strong> Both come from each region, so measurements read in µm and the zoom bar shows the objective. To set your own, see <a href="./calibration.html">Pixel Size and Magnification</a>.</li></ul><h2 id="if-a-slide-does-not-open" tabindex="-1">If a Slide Does Not Open <a class="header-anchor" href="#if-a-slide-does-not-open" aria-label="Permalink to &quot;If a Slide Does Not Open&quot;">​</a></h2><p>The viewer tells you why.</p><table tabindex="0"><thead><tr><th>What the file has</th><th>What the viewer says</th></tr></thead><tbody><tr><td>JPEG 2000 or another compression</td><td>This SCN file uses a compression the viewer cannot read yet.</td></tr></tbody></table><h2 id="annotations" tabindex="-1">Annotations <a class="header-anchor" href="#annotations" aria-label="Permalink to &quot;Annotations&quot;">​</a></h2><p>Import GeoJSON or OME-XML, and export both, from the <strong>Annotations</strong> panel. Send a link that opens the slide with its annotations. <a href="./annotation-exchange.html">Exchanging Annotations</a> shows how. To draw, measure and label shapes on the slide, see <a href="./annotations.html">Annotations</a>.</p><h2 id="public-slides-to-try" tabindex="-1">Public Slides to Try <a class="header-anchor" href="#public-slides-to-try" aria-label="Permalink to &quot;Public Slides to Try&quot;">​</a></h2><p><a href="https://openslide.org" target="_blank" rel="noreferrer">OpenSlide</a> shares test slides in its <a href="https://openslide.cs.cmu.edu/download/openslide-testdata/Leica/" target="_blank" rel="noreferrer">Leica folder</a>. Download a slide, then drop it on the viewer. They are marked distributable.</p><h2 id="for-your-it-team" tabindex="-1">For Your IT Team <a class="header-anchor" href="#for-your-it-team" aria-label="Permalink to &quot;For Your IT Team&quot;">​</a></h2><p>To open a slide by address, the server must answer byte-range requests and allow them through <a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/CORS" target="_blank" rel="noreferrer">CORS</a>. For a bucket, allow <code>GET</code> and the <code>Range</code> header in its CORS rules. <a href="./remote-urls.html#what-the-server-needs">What the Server Needs</a> has the details.</p><p>When a server cannot send parts of a file, the viewer says so. Download the slide and open it from your computer.</p><p>Addresses that start with <code>s3://</code> and <code>gs://</code> work too.</p><h2 id="image-credits" tabindex="-1">Image credits <a class="header-anchor" href="#image-credits" aria-label="Permalink to &quot;Image credits&quot;">​</a></h2><p>The screenshot uses <code>Leica-2.scn</code> from the OpenSlide test data, free to use and distribute. See <a href="./../sample-data.html">Sample Data and Credits</a>.</p><h2 id="privacy" tabindex="-1">Privacy <a class="header-anchor" href="#privacy" aria-label="Permalink to &quot;Privacy&quot;">​</a></h2><p>The slide is read in your browser. Opening one counts as one opened image of the kind &quot;Leica SCN file&quot;. The file name and address are never recorded. See the <a href="https://find-nuclei.github.io/privacy.html" target="_blank" rel="noreferrer">privacy policy</a>.</p><p><small>Product names are trademarks of their owners. Find Nuclei is not affiliated with them.</small></p>',22))])}const y=o(c,[["render",p]]);export{S as __pageData,y as default};
